-- Relational SQL export; MongoDB remains the system of record.
PRAGMA foreign_keys = ON;
PRAGMA defer_foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE "categories" ("_id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "parent_category_id" TEXT, "seasonal_tags" TEXT NOT NULL, "active_from" TEXT, "active_to" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, FOREIGN KEY ("parent_category_id") REFERENCES "categories" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("slug"));
CREATE TABLE "customers" ("_id" TEXT PRIMARY KEY, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "segment" TEXT, "region" TEXT, "attributes" TEXT NOT NULL, "is_active" INTEGER NOT NULL);
CREATE TABLE "products" ("_id" TEXT PRIMARY KEY, "category_id" TEXT, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "brand" TEXT, "attributes" TEXT NOT NULL, "price" TEXT NOT NULL, "currency" TEXT NOT NULL, "status" TEXT NOT NULL, "available_from" TEXT, "available_to" TEXT, "is_cold_start" INTEGER NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, FOREIGN KEY ("category_id") REFERENCES "categories" ("_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sessions" ("_id" TEXT PRIMARY KEY, "customer_id" TEXT NOT NULL, "started_at" TEXT NOT NULL, "ended_at" TEXT, "source" TEXT, "device" TEXT, "is_bot" INTEGER NOT NULL, "is_noisy" INTEGER NOT NULL, FOREIGN KEY ("customer_id") REFERENCES "customers" ("_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "page_views" ("_id" TEXT PRIMARY KEY, "session_id" TEXT NOT NULL, "customer_id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "occurred_at" TEXT NOT NULL, "sequence" INTEGER NOT NULL, "referrer" TEXT, FOREIGN KEY ("session_id") REFERENCES "sessions" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("customer_id") REFERENCES "customers" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("product_id") REFERENCES "products" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("session_id", "sequence"));
CREATE TABLE "carts" ("_id" TEXT PRIMARY KEY, "customer_id" TEXT NOT NULL, "session_id" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "converted_at" TEXT, "status" TEXT NOT NULL, FOREIGN KEY ("customer_id") REFERENCES "customers" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("session_id") REFERENCES "sessions" ("_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cart_lines" ("_id" TEXT PRIMARY KEY, "cart_id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "unit_price" TEXT NOT NULL, "line_total" TEXT NOT NULL, "added_at" TEXT NOT NULL, FOREIGN KEY ("cart_id") REFERENCES "carts" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("product_id") REFERENCES "products" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("cart_id", "product_id"));
CREATE TABLE "orders" ("_id" TEXT PRIMARY KEY, "customer_id" TEXT NOT NULL, "session_id" TEXT, "cart_id" TEXT, "placed_at" TEXT NOT NULL, "status" TEXT NOT NULL, "currency" TEXT NOT NULL, "subtotal" TEXT NOT NULL, "discount_total" TEXT NOT NULL, "tax_total" TEXT NOT NULL, "shipping_total" TEXT NOT NULL, "total" TEXT NOT NULL, FOREIGN KEY ("customer_id") REFERENCES "customers" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("session_id") REFERENCES "sessions" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("cart_id") REFERENCES "carts" ("_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "order_lines" ("_id" TEXT PRIMARY KEY, "order_id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "unit_price" TEXT NOT NULL, "discount" TEXT NOT NULL, "line_total" TEXT NOT NULL, FOREIGN KEY ("order_id") REFERENCES "orders" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("product_id") REFERENCES "products" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("order_id", "product_id"));
CREATE TABLE "product_relations" ("_id" TEXT PRIMARY KEY, "source_product_id" TEXT NOT NULL, "target_product_id" TEXT NOT NULL, "relation_type" TEXT NOT NULL, "weight" INTEGER NOT NULL, "created_at" TEXT NOT NULL, FOREIGN KEY ("source_product_id") REFERENCES "products" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("target_product_id") REFERENCES "products" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("source_product_id", "target_product_id", "relation_type"));
CREATE TABLE "lifecycle_events" ("_id" TEXT PRIMARY KEY, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "previous_state" TEXT, "new_state" TEXT NOT NULL, "event_type" TEXT NOT NULL, "occurred_at" TEXT NOT NULL, "sequence" INTEGER NOT NULL, "source_type" TEXT NOT NULL, "source_id" TEXT NOT NULL, "reference_id" TEXT, "metadata" TEXT NOT NULL, UNIQUE ("entity_type", "entity_id", "sequence"));
CREATE TABLE "dataset_splits" ("_id" TEXT PRIMARY KEY, "dataset_version" TEXT NOT NULL, "split_name" TEXT NOT NULL, "start_at" TEXT NOT NULL, "end_at" TEXT NOT NULL, "created_at" TEXT NOT NULL, "event_count" INTEGER NOT NULL, UNIQUE ("dataset_version", "split_name"));
CREATE TABLE "ground_truth_labels" ("_id" TEXT PRIMARY KEY, "customer_id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "source_event_id" TEXT NOT NULL, "dataset_split_id" TEXT NOT NULL, "event_type" TEXT NOT NULL, "occurred_at" TEXT NOT NULL, "relevance" INTEGER NOT NULL, FOREIGN KEY ("customer_id") REFERENCES "customers" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("product_id") REFERENCES "products" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("source_event_id") REFERENCES "order_lines" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("dataset_split_id") REFERENCES "dataset_splits" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("source_event_id"));
CREATE TABLE "anomaly_fixtures" ("_id" TEXT PRIMARY KEY, "anomaly_id" TEXT NOT NULL, "issue_type" TEXT NOT NULL, "severity" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "source_record_ids" TEXT NOT NULL, "generation_run_id" TEXT NOT NULL, "detected_at" TEXT NOT NULL, "description" TEXT NOT NULL, "ground_truth_label" TEXT NOT NULL, "fixture_records" TEXT NOT NULL, FOREIGN KEY ("generation_run_id") REFERENCES "generation_runs" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("anomaly_id"));
CREATE TABLE "generation_runs" ("_id" TEXT PRIMARY KEY, "seed" INTEGER NOT NULL, "configuration" TEXT NOT NULL, "status" TEXT NOT NULL, "started_at" TEXT NOT NULL, "completed_at" TEXT, "collection_counts" TEXT NOT NULL, "checksums" TEXT NOT NULL, "error" TEXT);
CREATE TABLE "validation_issues" ("_id" TEXT PRIMARY KEY, "issue_id" TEXT NOT NULL, "issue_type" TEXT NOT NULL, "severity" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT, "source_record_ids" TEXT NOT NULL, "generation_run_id" TEXT NOT NULL, "detected_at" TEXT NOT NULL, "description" TEXT NOT NULL, "ground_truth_label" TEXT NOT NULL, FOREIGN KEY ("generation_run_id") REFERENCES "generation_runs" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("issue_id"));
CREATE TABLE "recommendations" ("_id" TEXT PRIMARY KEY, "customer_id" TEXT NOT NULL, "session_id" TEXT, "model_run_id" TEXT, "generation_run_id" TEXT, "strategy" TEXT NOT NULL, "k" INTEGER NOT NULL, "model_version" TEXT NOT NULL, "source_interaction_ids" TEXT NOT NULL, "requested_at" TEXT NOT NULL, "as_of_time" TEXT NOT NULL, "training_cutoff" TEXT, "purchased_exclusion_rule" TEXT NOT NULL, "status" TEXT NOT NULL, "items" TEXT NOT NULL, FOREIGN KEY ("customer_id") REFERENCES "customers" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("model_run_id") REFERENCES "model_runs" ("_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "model_runs" ("_id" TEXT PRIMARY KEY, "algorithm" TEXT NOT NULL, "model_version" TEXT NOT NULL, "dataset_version" TEXT NOT NULL, "training_split_id" TEXT NOT NULL, "training_cutoff" TEXT NOT NULL, "parameters" TEXT NOT NULL, "feature_sources" TEXT NOT NULL, "status" TEXT NOT NULL, "created_at" TEXT NOT NULL, "completed_at" TEXT, FOREIGN KEY ("training_split_id") REFERENCES "dataset_splits" ("_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "evaluation_results" ("_id" TEXT PRIMARY KEY, "model_run_id" TEXT NOT NULL, "dataset_split_id" TEXT NOT NULL, "k" INTEGER NOT NULL, "evaluated_at" TEXT NOT NULL, "sample_count" INTEGER NOT NULL, "metrics" TEXT NOT NULL, FOREIGN KEY ("model_run_id") REFERENCES "model_runs" ("_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY ("dataset_split_id") REFERENCES "dataset_splits" ("_id") DEFERRABLE INITIALLY DEFERRED, UNIQUE ("model_run_id", "dataset_split_id", "k"));
COMMIT;
